import{_ as t,o as s,c as e,a5 as d}from"./chunks/framework.CslsFoWx.js";const b=JSON.parse('{"title":"Fournisseurs & achats","description":"","frontmatter":{"pageClass":"wide","aside":false},"headers":[],"relativePath":"modules/07-suppliers.md","filePath":"generated/modules/07-suppliers.md","lastUpdated":null}'),n={name:"modules/07-suppliers.md"};function r(o,a,i,p,u,c){return s(),e("div",null,[...a[0]||(a[0]=[d('<h1 id="fournisseurs-achats" tabindex="-1">Fournisseurs &amp; achats <a class="header-anchor" href="#fournisseurs-achats" aria-label="Permalink to &quot;Fournisseurs &amp; achats&quot;">​</a></h1><p><span class="badge partial">Partiel</span> <span class="muted">Phase 3 · <a href="/VendoraSystem-docs/specs/07-suppliers">spécification complète</a></span></p><p>Fournisseurs, bons de commande suggérés et envoyés, réceptions sur les caisses avec coût moyen pondéré (lot 3.6) ; factures, échéances, paiements partiels, relevé et retours avec avoir (lot 3.7).</p><div class="kpis"><div><b>18</b><span>faites</span></div><div><b>2</b><span>partielles</span></div><div><b>3</b><span>à faire</span></div><div><b>0</b><span>bloquées</span></div></div><h2 id="fournisseurs" tabindex="-1">Fournisseurs <a class="header-anchor" href="#fournisseurs" aria-label="Permalink to &quot;Fournisseurs&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Fonctionnalité</th><th>Statut</th><th>Partagé</th><th>Serveur</th><th>Android</th><th>iOS</th><th>Web</th><th>Règles</th><th>Lots</th><th>Preuve</th></tr></thead><tbody><tr><td><strong>Fiche fournisseur</strong><br><span class="muted">Le gérant crée un fournisseur partagé par le tenant, avec coordonnées, conditions de paiement, et peut le désactiver sans perdre l&#39;historique.<br><i>Fiches du tenant au back-office (coordonnées, délai de paiement, devise), recherche, désactivation sans suppression ; les caisses ne gèrent pas les fournisseurs.</i></span></td><td><span class="badge ok">Fait</span></td><td><span class="badge todo">À faire</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge todo">À faire</span></td><td><span class="badge todo">À faire</span></td><td><span class="badge ok">Fait</span></td><td>RG-SUP-01, RG-SUP-02</td><td>3.6</td><td><a href="/VendoraSystem-docs/preuves/2026-10-31-achats">📷</a></td></tr><tr><td><strong>Produits fournis</strong><br><span class="muted">Chaque lien produit-fournisseur porte prix d&#39;achat, référence, minimum de commande, colisage et un fournisseur préféré.<br><i>Prix d&#39;achat, référence fournisseur, colisage, un seul fournisseur préféré par produit (index unique).</i></span></td><td><span class="badge ok">Fait</span></td><td><span class="badge todo">À faire</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge todo">À faire</span></td><td><span class="badge todo">À faire</span></td><td><span class="badge ok">Fait</span></td><td>RG-SUP-03</td><td>3.6</td><td><a href="/VendoraSystem-docs/preuves/2026-10-31-achats">📷</a></td></tr><tr><td><strong>Prix d&#39;achat masquables</strong><br><span class="muted">Le tenant peut masquer les prix d&#39;achat et les marges aux rôles non gérants.<br><i>Phase 3 (option tenant, spec 07 §8).</i></span></td><td><span class="badge todo">À faire</span></td><td><span class="badge na">—</span></td><td><span class="badge todo">À faire</span></td><td><span class="badge na">—</span></td><td><span class="badge na">—</span></td><td><span class="badge todo">À faire</span></td><td></td><td></td><td></td></tr></tbody></table><h2 id="bons-de-commande" tabindex="-1">Bons de commande <a class="header-anchor" href="#bons-de-commande" aria-label="Permalink to &quot;Bons de commande&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Fonctionnalité</th><th>Statut</th><th>Partagé</th><th>Serveur</th><th>Android</th><th>iOS</th><th>Web</th><th>Règles</th><th>Lots</th><th>Preuve</th></tr></thead><tbody><tr><td><strong>Bon de commande et cycle de vie</strong><br><span class="muted">Le gérant crée un bon en brouillon, modifiable seulement à ce stade, qui passe ensuite par envoyé, partiellement reçu, reçu ou annulé.<br><i>Transitions de RG-SUP-04 partagées ; brouillon modifiable avec verrou de version (409) ; annulation refusée dès qu&#39;une réception existe ; les caisses reçoivent les bons envoyés.</i></span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td>RG-SUP-04, RG-SUP-05</td><td>3.6</td><td><a href="/VendoraSystem-docs/preuves/2026-10-31-achats">📷</a></td></tr><tr><td><strong>Numérotation des bons</strong><br><span class="muted">Le serveur attribue un numéro séquentiel par magasin au passage à l&#39;état envoyé.<br><i>PO-&lt;code magasin&gt;-&lt;année&gt;-&lt;seq&gt; attribué par le serveur à l&#39;envoi, séquence par magasin et par année, accents translittérés.</i></span></td><td><span class="badge ok">Fait</span></td><td><span class="badge todo">À faire</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge todo">À faire</span></td><td><span class="badge todo">À faire</span></td><td><span class="badge ok">Fait</span></td><td>RG-SUP-06</td><td>3.6</td><td><a href="/VendoraSystem-docs/preuves/2026-10-31-achats">📷</a></td></tr><tr><td><strong>Suggestion automatique de commande</strong><br><span class="muted">Le système propose un brouillon par fournisseur préféré pour les produits sous leur seuil, quantités arrondies au colisage.<br><i>Seuil de stock bas par produit, ventes des 30 derniers jours, couverture 14 jours, déjà commandé, colisage ; un brouillon par fournisseur préféré, produits sans préféré « à affecter », jamais envoyé seul.</i></span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge todo">À faire</span></td><td><span class="badge todo">À faire</span></td><td><span class="badge ok">Fait</span></td><td>RG-SUP-07</td><td>3.6</td><td><a href="/VendoraSystem-docs/preuves/2026-10-31-achats">📷</a></td></tr><tr><td><strong>Envoi du bon par email avec PDF</strong><br><span class="muted">L&#39;envoi génère un PDF aux couleurs du magasin et l&#39;adresse au fournisseur par email, l&#39;action étant tracée.<br><i>PDF A4 (PDFBox) joint au mail du fournisseur ; sans email, le bon passe quand même en envoyé (PDF à remettre) ; envoi SMTP réel prêt (tout fournisseur, variables POS_MAIL_*) ; en dev, boîte simulée.</i></span></td><td><span class="badge ok">Fait</span></td><td><span class="badge todo">À faire</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge todo">À faire</span></td><td><span class="badge todo">À faire</span></td><td><span class="badge ok">Fait</span></td><td>RG-SUP-08</td><td>3.6</td><td><a href="/VendoraSystem-docs/preuves/2026-10-31-achats">📷</a></td></tr><tr><td><strong>Clôture d&#39;un reliquat</strong><br><span class="muted">Le gérant clôture un bon partiellement reçu en abandonnant le reliquat avec un motif.<br><i>Bon reçu en partie clôturé avec motif obligatoire, audité ; le PIN manager pour un MANAGER au back-office reste à faire.</i></span></td><td><span class="badge ok">Fait</span></td><td><span class="badge todo">À faire</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge todo">À faire</span></td><td><span class="badge todo">À faire</span></td><td><span class="badge ok">Fait</span></td><td>RG-SUP-14</td><td>3.6</td><td><a href="/VendoraSystem-docs/preuves/2026-10-31-achats">📷</a></td></tr></tbody></table><h2 id="receptions" tabindex="-1">Réceptions <a class="header-anchor" href="#receptions" aria-label="Permalink to &quot;Réceptions&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Fonctionnalité</th><th>Statut</th><th>Partagé</th><th>Serveur</th><th>Android</th><th>iOS</th><th>Web</th><th>Règles</th><th>Lots</th><th>Preuve</th></tr></thead><tbody><tr><td><strong>Réception scannée sur mobile</strong><br><span class="muted">Le gérant réceptionne une livraison en scannant les produits sur son téléphone, ce qui génère un mouvement RECEPTION par ligne.<br><i>Menu « Réceptions fournisseur » (managers) sur Android et iPhone : bons attendus, scan douchette qui incrémente, saisie, « Tout reçu », un mouvement RECEPTION signé par ligne ; scan caméra à la réception encore à faire.</i></span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td>RG-SUP-09, RG-SUP-10</td><td>3.6</td><td><a href="/VendoraSystem-docs/preuves/2026-10-31-achats">📷</a></td></tr><tr><td><strong>Réception directe sans commande</strong><br><span class="muted">Une livraison sans bon de commande peut être réceptionnée, tracée comme réception directe.<br><i>Au back-office (API) : sans commande, fournisseur et coût obligatoires, tracée comme telle ; pas encore sur les caisses.</i></span></td><td><span class="badge ok">Fait</span></td><td><span class="badge todo">À faire</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge todo">À faire</span></td><td><span class="badge todo">À faire</span></td><td><span class="badge ok">Fait</span></td><td>RG-SUP-09</td><td>3.6</td><td><a href="/VendoraSystem-docs/preuves/2026-10-31-achats">📷</a></td></tr><tr><td><strong>Écarts commandé / reçu</strong><br><span class="muted">Chaque manque, surplus, casse ou substitution est motivé sur la ligne ; un surplus de plus de 20 % demande confirmation.<br><i>Manquant en orange, surplus en rouge, motif modifiable (casse, substitution) ; surplus de plus de 20 % à confirmer ; cumul concurrent au-delà de la commande marqué surplus par le serveur.</i></span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td>RG-SUP-11</td><td>3.6</td><td><a href="/VendoraSystem-docs/preuves/2026-10-31-achats">📷</a></td></tr><tr><td><strong>Mise à jour du CMP</strong><br><span class="muted">Le serveur recalcule le coût moyen pondéré à chaque ligne de réception, dans l&#39;ordre des réceptions.<br><i>CMP par magasin recalculé par le serveur à chaque ligne (règle partagée, arrondi au plus proche), affiché dans la page Stock.</i></span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge todo">À faire</span></td><td><span class="badge todo">À faire</span></td><td><span class="badge ok">Fait</span></td><td>RG-SUP-12</td><td>3.6</td><td><a href="/VendoraSystem-docs/preuves/2026-10-31-achats">📷</a></td></tr><tr><td><strong>Lots et DLC à la réception</strong><br><span class="muted">Sur une ligne suivie en péremption, la réception exige un numéro de lot et une DLC, accepte plusieurs lots par ligne et alimente les lots du stock.<br><i>Back-office au lot 4.3 (422 LOT_REQUIRED). 11/11 : saisie sur la caisse, iOS et Android — lot et DLC par ligne suivie, « Ajouter un lot » pour répartir une ligne sur plusieurs lots, total « Lots : n sur n reçus », validation bloquée tant qu&#39;un lot manque ; le serveur crée les lots d&#39;une réception poussée par la caisse et diffuse StockLotUpdated ; une ancienne app qui pousse sans lot est acceptée et tracée (RECEPTION / LOT_MISSING). Captures iPad et tablette Android (refus sans lot, deux lots et DLC, réception enregistrée, choix du lot à la vente).</i></span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td>RG-SUP-13, RG-STOCK-12, RG-STOCK-13</td><td>4.3, cartes-11/11</td><td><a href="/VendoraSystem-docs/preuves/2026-11-11-reception-lots-caisse">📷</a></td></tr><tr><td><strong>Réception hors ligne</strong><br><span class="muted">Une réception validée sans internet met le stock local à jour et converge sans doublon au retour du réseau.<br><i>Réception validée sans réseau : stock local immédiat, statut provisoire, idempotence par identifiant au push.</i></span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge todo">À faire</span></td><td>RG-SUP-10</td><td>3.6</td><td><a href="/VendoraSystem-docs/preuves/2026-10-31-achats">📷</a></td></tr><tr><td><strong>Étiquettes depuis une réception</strong><br><span class="muted">Le gérant imprime les étiquettes des produits d&#39;une réception fournisseur.<br><i>Reste du lot étiquettes (phase 1) : la sélection par réception attend les réceptions (phase 3).</i></span></td><td><span class="badge todo">À faire</span></td><td><span class="badge na">—</span></td><td><span class="badge todo">À faire</span></td><td><span class="badge na">—</span></td><td><span class="badge na">—</span></td><td><span class="badge todo">À faire</span></td><td>RG-CAT-45</td><td></td><td></td></tr></tbody></table><h2 id="dettes-fournisseurs" tabindex="-1">Dettes fournisseurs <a class="header-anchor" href="#dettes-fournisseurs" aria-label="Permalink to &quot;Dettes fournisseurs&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Fonctionnalité</th><th>Statut</th><th>Partagé</th><th>Serveur</th><th>Android</th><th>iOS</th><th>Web</th><th>Règles</th><th>Lots</th><th>Preuve</th></tr></thead><tbody><tr><td><strong>Factures fournisseur</strong><br><span class="muted">Le gérant enregistre une facture rattachée aux réceptions, avec une échéance calculée selon les conditions du fournisseur.<br><i>Facture par magasin rattachée aux réceptions, échéance par défaut = date + délai du fournisseur, doublon refusé ; page Dettes fournisseurs.</i></span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge todo">À faire</span></td><td><span class="badge todo">À faire</span></td><td><span class="badge ok">Fait</span></td><td>RG-SUP-15</td><td>3.7</td><td><a href="/VendoraSystem-docs/preuves/2026-10-31-dettes-fournisseurs">📷</a></td></tr><tr><td><strong>Paiements partiels</strong><br><span class="muted">Le propriétaire enregistre des paiements partiels ; le statut de la facture est dérivé et jamais négatif.<br><i>Paiements partiels (virement, chèque, espèces, autre), jamais au-delà du solde ; statut Impayée / Payée en partie / Payée dérivé (règle partagée).</i></span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge todo">À faire</span></td><td><span class="badge todo">À faire</span></td><td><span class="badge ok">Fait</span></td><td>RG-SUP-16</td><td>3.7</td><td><a href="/VendoraSystem-docs/preuves/2026-10-31-dettes-fournisseurs">📷</a></td></tr><tr><td><strong>Solde et alertes d&#39;échéance</strong><br><span class="muted">Le propriétaire voit ce qu&#39;il doit à chaque fournisseur et les factures bientôt dues ou en retard.<br><i>Solde = factures ouvertes − avoirs ; alertes à J−7 et en retard au tableau de bord, dans la liste des fournisseurs et la page des dettes ; relevé chronologique. Notifications push et email à faire.</i></span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge todo">À faire</span></td><td><span class="badge todo">À faire</span></td><td><span class="badge ok">Fait</span></td><td>RG-SUP-17</td><td>3.7</td><td><a href="/VendoraSystem-docs/preuves/2026-10-31-dettes-fournisseurs">📷</a></td></tr><tr><td><strong>Achat fournisseur payé en espèces</strong><br><span class="muted">Le caissier enregistre une sortie d&#39;espèces au motif « achat fournisseur », comptée dans le théorique et le Z.<br><i>Motif disponible en caisse (spec 04) ; aucun rattachement à un fournisseur ni à une facture, à faire avec le module (phase 3).</i></span></td><td><span class="badge partial">Partiel</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td>RG-CASH-05</td><td>1.x</td><td><a href="/VendoraSystem-docs/preuves/2026-10-29-rapport-x-android">📷</a> <a href="/VendoraSystem-docs/preuves/2026-10-29-rapport-x-ios">📷</a></td></tr></tbody></table><h2 id="prix-retours" tabindex="-1">Prix &amp; retours <a class="header-anchor" href="#prix-retours" aria-label="Permalink to &quot;Prix &amp; retours&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Fonctionnalité</th><th>Statut</th><th>Partagé</th><th>Serveur</th><th>Android</th><th>iOS</th><th>Web</th><th>Règles</th><th>Lots</th><th>Preuve</th></tr></thead><tbody><tr><td><strong>Historique et comparaison des prix</strong><br><span class="muted">Chaque coût constaté en réception est historisé, et le propriétaire compare dernier prix et tendance par fournisseur.<br><i>Coût constaté à chaque réception par produit et fournisseur ; comparaison (dernier prix, tendance) dans la page Stock ; la mise à jour du prix courant reste manuelle.</i></span></td><td><span class="badge ok">Fait</span></td><td><span class="badge todo">À faire</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge todo">À faire</span></td><td><span class="badge todo">À faire</span></td><td><span class="badge ok">Fait</span></td><td>RG-SUP-18</td><td>3.6</td><td><a href="/VendoraSystem-docs/preuves/2026-10-31-achats">📷</a></td></tr><tr><td><strong>Retour fournisseur</strong><br><span class="muted">Le manager valide sous PIN un retour de produits défectueux ou périmés, qui sort le stock et crée un avoir éventuel.<br><i>Au back-office : motif, lignes, avoir déduit du solde, mouvement SUPPLIER_RETURN descendu aux caisses ; retour depuis une caisse sous PIN manager à faire.</i></span></td><td><span class="badge partial">Partiel</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge todo">À faire</span></td><td><span class="badge todo">À faire</span></td><td><span class="badge ok">Fait</span></td><td>RG-SUP-19</td><td>3.7</td><td><a href="/VendoraSystem-docs/preuves/2026-10-31-dettes-fournisseurs">📷</a></td></tr><tr><td><strong>Journal d&#39;audit des achats</strong><br><span class="muted">Création, envoi, annulation, réception, clôture de reliquat, paiement et retour sont journalisés.<br><i>Commandes, réceptions, clôtures, seuils, factures, paiements et retours journalisés.</i></span></td><td><span class="badge ok">Fait</span></td><td><span class="badge todo">À faire</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge todo">À faire</span></td><td><span class="badge todo">À faire</span></td><td><span class="badge ok">Fait</span></td><td>RG-SUP-20</td><td>3.6, 3.7</td><td><a href="/VendoraSystem-docs/preuves/2026-10-31-achats">📷</a> <a href="/VendoraSystem-docs/preuves/2026-10-31-dettes-fournisseurs">📷</a></td></tr></tbody></table><h2 id="vision" tabindex="-1">Vision <a class="header-anchor" href="#vision" aria-label="Permalink to &quot;Vision&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Fonctionnalité</th><th>Statut</th><th>Partagé</th><th>Serveur</th><th>Android</th><th>iOS</th><th>Web</th><th>Règles</th><th>Lots</th><th>Preuve</th></tr></thead><tbody><tr><td><strong>Annuaire et marketplace fournisseurs</strong><br><span class="muted">Le commerçant cherche un fournisseur, compare les prix de sa zone et commande depuis le POS.<br><i>Hors v1 : vision phase 4+, spec dédiée à écrire.</i></span></td><td><span class="badge todo">À faire</span></td><td><span class="badge na">—</span></td><td><span class="badge todo">À faire</span></td><td><span class="badge na">—</span></td><td><span class="badge na">—</span></td><td><span class="badge todo">À faire</span></td><td></td><td></td><td></td></tr></tbody></table><h2 id="reste-a-faire" tabindex="-1">Reste à faire <a class="header-anchor" href="#reste-a-faire" aria-label="Permalink to &quot;Reste à faire&quot;">​</a></h2><ul><li>Retour fournisseur depuis une caisse sous PIN manager ; notifications d&#39;échéance (push, email) aux managers.</li><li>Scan caméra à la réception sur les caisses.</li><li>PIN manager pour la clôture d&#39;un reliquat par un MANAGER ; masquage des prix d&#39;achat selon le rôle.</li><li>Rattacher les sorties d&#39;espèces « achat fournisseur » à une fiche et une facture ; fournisseur SMTP réel.</li><li>Annuaire / marketplace fournisseurs : hors v1.</li></ul>',18)])])}const g=t(n,[["render",r]]);export{b as __pageData,g as default};
